function results = run_all(figure_dir)
%RUN_ALL Run every MATLAB study of the State-Space Studio project.
%   results = RUN_ALL() adds the project folders to the path, runs the three studies
%   and leaves their figures open.
%   results = RUN_ALL(figure_dir) additionally writes every figure as PNG to FIGURE_DIR.
%
%   Requirements: MATLAB R2020a or newer with the Control System Toolbox.
%   The optional Simulink models are generated by simulink/build_simulink_models.m.

if nargin < 1
    figure_dir = "";
end
root = fileparts(mfilename('fullpath'));
addpath(fullfile(root, 'models'), fullfile(root, 'toolbox'), fullfile(root, 'studies'));

opts = struct('figure_dir', string(figure_dir));
if strlength(opts.figure_dir) > 0 && ~isfolder(opts.figure_dir)
    mkdir(opts.figure_dir);
end

results.fundamentals = study_01_fundamentals(opts);
results.drivetrain = study_02_drivetrain(opts);
results.three_tank = study_03_three_tank(opts);
end
